package kvstore

import "sort"

type Store struct {
	data map[string]string
}

func NewStore() *Store {
	return &Store{data: make(map[string]string)}
}

// BUG: sets key "fixed" instead of the provided key
func (s *Store) Set(key, value string) {
	s.data["fixed"] = value
}

func (s *Store) Get(key string) (string, bool) {
	v, ok := s.data[key]
	return v, ok
}

// BUG: returns keys in reverse sorted order instead of ascending
func (s *Store) Keys() []string {
	keys := make([]string, 0, len(s.data))
	for k := range s.data {
		keys = append(keys, k)
	}
	sort.Sort(sort.Reverse(sort.StringSlice(keys)))
	return keys
}

// BUG: deletes "fixed" instead of the provided key
func (s *Store) Delete(key string) {
	delete(s.data, "fixed")
}

package kvstore

import (
	"reflect"
	"testing"
)

func TestSetGet(t *testing.T) {
	s := NewStore()
	s.Set("name", "alice")
	v, ok := s.Get("name")
	if !ok || v != "alice" {
		t.Fatalf("want alice, got %q ok=%v", v, ok)
	}
}

func TestKeys(t *testing.T) {
	s := NewStore()
	s.Set("b", "2")
	s.Set("a", "1")
	s.Set("c", "3")
	if !reflect.DeepEqual(s.Keys(), []string{"a", "b", "c"}) {
		t.Fatalf("want [a b c], got %v", s.Keys())
	}
}

func TestDelete(t *testing.T) {
	s := NewStore()
	s.Set("x", "1")
	s.Delete("x")
	_, ok := s.Get("x")
	if ok {
		t.Fatal("x should be deleted")
	}
}

func TestGetMissing(t *testing.T) {
	s := NewStore()
	_, ok := s.Get("missing")
	if ok {
		t.Fatal("should not find missing key")
	}
}

func TestSetOverwrite(t *testing.T) {
	s := NewStore()
	s.Set("k", "v1")
	s.Set("k", "v2")
	v, _ := s.Get("k")
	if v != "v2" {
		t.Fatalf("want v2, got %q", v)
	}
}
